        /// <summary>
        /// Block CGLS for a TALL/overdetermined operator A (A.Rows &gt;= A.Cols, full column rank)
        /// and s simultaneous right-hand sides: minimizes the Frobenius norm ‖A X - B‖_F by running
        /// block-CG on the normal equations Aᵀ A X = Aᵀ B WITHOUT ever forming Aᵀ A -- only A and Aᵀ
        /// applies (Hestenes-Stiefel recurrence, block-generalized). Reuses the same s x s Gram /
        /// block-coefficient-solve machinery as <see cref="bcg{TOp, TPre}"/>; the operator is applied
        /// per row (<c>Apply</c>/<c>ApplyT</c>) the way <see cref="blsmr{TOp}"/> does, since
        /// <see cref="IdoubleLinearOperator.ApplyBlock"/> is symmetric/square-only.
        ///
        /// B and X are s ROWS x (A.Rows / A.Cols) COLS respectively (row j = the j-th RHS/solution
        /// vector). X is NOT warm-startable -- this overload always overwrites X from zero (mirrors
        /// <see cref="blsmr{TOp}"/>). Owns its whole workspace via Allocator.Temp.
        ///
        /// Convergence is the normal-equation residual ‖Aᵀ(AX-B)‖ per column, against
        /// tol²·‖Aᵀ B[j]‖² (the classical CGLS scale). <see cref="BlockSolveInfo.maxRnorm"/> is the
        /// worst RAW least-squares residual ‖B[j] - A X[j]‖ at the returned X, matching
        /// <see cref="BlockSolveInfo"/>'s documented contract. The s x s block solves (QᵀQ for alpha,
        /// the running Gram for beta) go through <see cref="BlockSolveSPD"/>'s ridge-fallback ladder;
        /// only a total ladder failure is a <see cref="IterativeSolveStatus.Breakdown"/>.
        /// <see cref="BlockSolveInfo.minActive"/> is always s (no column deflation).
        /// </summary>
        public static BlockSolveInfo bcgls<TOp>(in TOp A, in doubleMxN B, ref doubleMxN X, int maxIter, double tol)
            where TOp : struct, IdoubleLinearOperator
        {
            if (A.Rows < A.Cols) throw new ArgumentException("bcgls: A must be tall or square (A.Rows >= A.Cols)");
            int m = A.Rows, n = A.Cols;
            int s = B.M_Rows;
            if (B.N_Cols != m) throw new ArgumentException("bcgls: B.N_Cols must equal A.Rows");
            if (X.M_Rows != s || X.N_Cols != n) throw new ArgumentException("bcgls: X must be s x A.Cols");
            if (maxIter < 1) throw new ArgumentException("bcgls: maxIter must be >= 1");

            for (int i = 0; i < s; i++)
                for (int c = 0; c < n; c++) X[i, c] = (double)0;

            doubleN rowN = new doubleN(n), rowM = new doubleN(m);

            var R    = new doubleMxN(s, m, Allocator.Temp, true);   // raw residual B - A X
            var S    = new doubleMxN(s, n, Allocator.Temp, true);   // normal-eq residual A^T R
            var P    = new doubleMxN(s, n, Allocator.Temp, true);   // search block
            var Q    = new doubleMxN(s, m, Allocator.Temp, true);   // A P
            var TN   = new doubleMxN(s, n, Allocator.Temp, true);   // s x n GEMM scratch
            var TM   = new doubleMxN(s, m, Allocator.Temp, true);   // s x m GEMM scratch

            var gamma    = new doubleMxN(s, s, Allocator.Temp, true);   // S^T S (row-Gram)
            var gammaNew = new doubleMxN(s, s, Allocator.Temp, true);
            var QtQ      = new doubleMxN(s, s, Allocator.Temp, true);
            var coef     = new doubleMxN(s, s, Allocator.Temp, true);
            var work     = new doubleMxN(s, s, Allocator.Temp, true);
            var thr      = new doubleN(s);

            IterativeSolveStatus status = IterativeSolveStatus.MaxIterations;
            int iters = 0;
            int converged = 0;

            CopyBlock(in B, ref R, s, m);                              // R0 = B - A X0 = B (X0 = 0)
            BlockApplyOpT(in A, in R, ref S, s, ref rowN, ref rowM);    // S0 = A^T R0
            BlockGram(in S, in S, ref gamma, s);                       // gamma0 = S0^T S0

            for (int j = 0; j < s; j++) thr[j] = tol * tol * gamma[j, j];

            converged = CountConverged(in S, in thr, s, n, out double maxrS0);
            if (converged == s)
            {
                status = IterativeSolveStatus.Converged;
                iters = 0;
                goto cleanup;
            }

            CopyBlock(in S, ref P, s, n);                              // P0 = S0

            for (int k = 0; k < maxIter; k++)
            {
                BlockApplyOp(in A, in P, ref Q, s, ref rowN, ref rowM);   // Q = A P
                BlockGram(in Q, in Q, ref QtQ, s);                       // QtQ = Q^T Q (row-Gram)

                // alpha = (Q^T Q)^-1 gamma; coef <- gamma, solved in place.
                CopyMat(in gamma, ref coef, s);
                if (!BlockSolveSPD(in QtQ, ref coef, ref work, s))
                { status = IterativeSolveStatus.Breakdown; iters = k; goto cleanup; }

                BlockCTV(in coef, in P, ref TN); BlockAdd(ref X, in TN, (double)1);    // X += alpha^T P
                BlockCTV(in coef, in Q, ref TM); BlockAdd(ref R, in TM, (double)(-1)); // R -= alpha^T Q

                BlockApplyOpT(in A, in R, ref S, s, ref rowN, ref rowM);  // S = A^T R
                BlockGram(in S, in S, ref gammaNew, s);                  // gamma_{k+1} = S^T S

                converged = CountConverged(in S, in thr, s, n, out double maxrS);
                if (converged == s)
                { status = IterativeSolveStatus.Converged; iters = k + 1; goto cleanup; }

                // beta = gamma_k^-1 gamma_{k+1}; coef <- gammaNew, solved in place against the OLD gamma.
                CopyMat(in gammaNew, ref coef, s);
                if (!BlockSolveSPD(in gamma, ref coef, ref work, s))
                { status = IterativeSolveStatus.Breakdown; iters = k + 1; goto cleanup; }

                BlockCTV(in coef, in P, ref TN);      // TN = beta^T P
                BlockZplusT(in S, in TN, ref P);       // P = S + beta^T P

                CopyMat(in gammaNew, ref gamma, s);
                iters = k + 1;
            }

        cleanup:
            {
                double maxr = 0;
                for (int j = 0; j < s; j++)
                {
                    double rr = 0;
                    for (int c = 0; c < m; c++)
                    {
                        double d = (double)R[j, c];
                        rr += d * d;
                    }
                    double rn = math.sqrt(rr);
                    if (rn > maxr) maxr = rn;
                }

                rowN.Dispose(); rowM.Dispose();
                R.Dispose(); S.Dispose(); P.Dispose(); Q.Dispose(); TN.Dispose(); TM.Dispose();
                gamma.Dispose(); gammaNew.Dispose(); QtQ.Dispose(); coef.Dispose(); work.Dispose(); thr.Dispose();

                return new BlockSolveInfo { rhs = s, converged = converged, iterations = iters, maxRnorm = maxr, minActive = s, status = status };
            }
        }

